#Requires -Version 5.1
[CmdletBinding()]
param(
    [switch]$Uninstall,
    [string]$Endpoint       = $(if ($env:GATEWAY_ENDPOINT)       { $env:GATEWAY_ENDPOINT }       else { '__INJECT_ENDPOINT__' }),
    [string]$ApiKey         = $(if ($env:GATEWAY_API_KEY)        { $env:GATEWAY_API_KEY }        else { '__INJECT_API_KEY__' }),
    [string]$Model          = $(if ($env:GATEWAY_MODEL)          { $env:GATEWAY_MODEL }          else { '__INJECT_MODEL__' }),
    [string]$Targets        = $(if ($env:GATEWAY_TARGETS)        { $env:GATEWAY_TARGETS }        else { '__INJECT_TARGETS__' }),
    [string]$GlobalPolicy   = $(if ($env:GATEWAY_GLOBAL_POLICY)  { $env:GATEWAY_GLOBAL_POLICY }  else { '1' }),
    [string]$MigrateHistory = $(if ($env:GATEWAY_MIGRATE_HIST)   { $env:GATEWAY_MIGRATE_HIST }   else { '1' })
)

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
$Version = '7.0'

try {
    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 -bor 3072 -bor 12288
} catch {
    [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
}

if ($Endpoint -match '^__INJECT_') { $Endpoint = '' }
if ($ApiKey -match '^__INJECT_')   { $ApiKey = '' }
if ($Model -match '^__INJECT_')    { $Model = '' }
if ($Targets -match '^__INJECT_' -or [string]::IsNullOrWhiteSpace($Targets)) {
    $Targets = 'codex,opencode,claude-desktop,claude-code'
}

function Normalize-GatewayEndpoint([string]$RawUrl) {
    $u = $RawUrl.Trim().TrimEnd('/')
    if ([string]::IsNullOrWhiteSpace($u)) { return '' }
    if ($u -notmatch '^https?://') { $u = 'https://' + $u }
    if ($u -notmatch '/v1$') { $u = $u + '/v1' }
    return $u
}

function Broadcast-EnvironmentChange {
    try {
        if (-not ('GatewaySetup.EnvBroadcast' -as [type])) {
            Add-Type -TypeDefinition @'
using System;
using System.Runtime.InteropServices;
namespace GatewaySetup {
    public static class EnvBroadcast {
        [DllImport("user32.dll", CharSet=CharSet.Unicode, SetLastError=true)]
        private static extern IntPtr SendMessageTimeout(IntPtr hWnd, uint msg, UIntPtr wParam,
            string lParam, uint flags, uint timeout, out UIntPtr result);
        public static void Notify() {
            UIntPtr result;
            SendMessageTimeout(new IntPtr(0xffff), 0x001a, UIntPtr.Zero, "Environment", 2, 2000, out result);
        }
    }
}
'@
        }
        [GatewaySetup.EnvBroadcast]::Notify()
    } catch { }
}

$codexHome    = if ($env:CODEX_HOME) { [IO.Path]::GetFullPath($env:CODEX_HOME) } else { Join-Path $env:USERPROFILE '.codex' }
$claudePath   = Join-Path $env:USERPROFILE '.claude\settings.json'
$opencodePath = Join-Path $env:USERPROFILE '.config\opencode\opencode.json'
$hermesPath   = Join-Path $env:USERPROFILE '.hermes\config.yaml'
$openclawPath = Join-Path $env:USERPROFILE '.openclaw\openclaw.json'
$backupRoot   = Join-Path $env:USERPROFILE '.gateway\backups'

function Write-Utf8([string]$Path, [string]$Text) {
    $dir = Split-Path -Parent $Path
    if ($dir -and -not (Test-Path -LiteralPath $dir)) { $null = New-Item -ItemType Directory -Path $dir -Force }
    [IO.File]::WriteAllText($Path, $Text, (New-Object Text.UTF8Encoding($false)))
}

function ConvertTo-Hashtable($Value) {
    if ($null -eq $Value) { return $null }
    if ($Value -is [System.Collections.IDictionary]) {
        $h = @{}
        foreach ($k in $Value.Keys) { $h[$k] = ConvertTo-Hashtable $Value[$k] }
        return $h
    }
    if ($Value -is [System.Management.Automation.PSCustomObject]) {
        $h = @{}
        foreach ($p in $Value.PSObject.Properties) { $h[$p.Name] = ConvertTo-Hashtable $p.Value }
        return $h
    }
    if ($Value -is [System.Collections.IEnumerable] -and -not ($Value -is [string])) {
        return @($Value | ForEach-Object { ConvertTo-Hashtable $_ })
    }
    return $Value
}

function Restrict-File([string]$Path) {
    try {
        $acl = Get-Acl -LiteralPath $Path
        $acl.SetAccessRuleProtection($true, $false)
        $rule = New-Object System.Security.AccessControl.FileSystemAccessRule(
            [Security.Principal.WindowsIdentity]::GetCurrent().Name,
            'FullControl', 'Allow')
        $acl.AddAccessRule($rule)
        Set-Acl -LiteralPath $Path -AclObject $acl
    } catch { }
}

function Backup-File([string]$Path, [string]$Name, [string]$Dir, [hashtable]$Map) {
    if (Test-Path -LiteralPath $Path -PathType Leaf) {
        Copy-Item -LiteralPath $Path -Destination (Join-Path $Dir $Name) -Force
        $Map[$Name] = $Path
    }
}

if ($Uninstall) {
    Write-Output '[LOG] Restaurando padrao original...'
    $reqSys = Join-Path ([Environment]::GetFolderPath('CommonApplicationData')) 'OpenAI\Codex\requirements.toml'
    if (Test-Path -LiteralPath $reqSys) { Remove-Item -LiteralPath $reqSys -Force -ErrorAction SilentlyContinue }
    if (Test-Path -LiteralPath $backupRoot) {
        $latest = Get-ChildItem -LiteralPath $backupRoot -Directory -ErrorAction SilentlyContinue | Sort-Object Name -Descending | Select-Object -First 1
        if ($latest) {
            $manifestPath = Join-Path $latest.FullName 'manifest.json'
            if (Test-Path -LiteralPath $manifestPath) {
                $manifest = Get-Content -LiteralPath $manifestPath -Raw -Encoding UTF8 | ConvertFrom-Json
                foreach ($prop in $manifest.files.PSObject.Properties) {
                    $src = Join-Path $latest.FullName $prop.Name
                    if (Test-Path -LiteralPath $src) {
                        $target = [string]$prop.Value
                        $dir = Split-Path -Parent $target
                        if (-not (Test-Path -LiteralPath $dir)) { $null = New-Item -ItemType Directory -Path $dir -Force }
                        Copy-Item -LiteralPath $src -Destination $target -Force
                    }
                }
            }
        }
    }
    Broadcast-EnvironmentChange
    Write-Output '[LOG] Padrao restaurado.'
    Write-Output 'GATEWAY_RESTORE_OK'
    exit 0
}

$key = ($ApiKey -replace '\s', '')
if ($key -notmatch '^[A-Za-z0-9._:-]{6,256}$') { throw 'Chave de API invalida.' }
$cleanEp = Normalize-GatewayEndpoint $Endpoint
if ($cleanEp -notmatch '^https?://') { throw 'Endpoint invalido.' }

$targetList = @($Targets.ToLower().Split(',') | ForEach-Object { $_.Trim() } | Where-Object { $_ })

Write-Output '[LOG] Validando credencial e sincronizando catalogo real do Gateway...'
$headers = @{
    Authorization = ('Bearer ' + $key)
    'x-api-key'   = $key
    Accept        = 'application/json'
    'User-Agent'  = 'Gateway-Setup/7.0'
}

# Fetch ONLY the real models returned by the Gateway /models endpoint
$models = @()
try {
    $resp = Invoke-RestMethod -Uri ($cleanEp + '/models') -Headers $headers -Method Get -TimeoutSec 25
    foreach ($item in @($resp.data)) {
        $mid = [string]$item.id
        if ($mid -and ($mid -notmatch '^aihorde/') -and ($models -notcontains $mid)) {
            $models += $mid
        }
    }
} catch {
    throw ('Falha ao consultar catalogo em /models: ' + $_.Exception.Message)
}

if ($models.Count -eq 0) {
    throw 'A API nao retornou nenhum modelo para esta chave.'
}

Write-Output "[LOG] Catalogo validado ($($models.Count) modelos reais recebidos)."

$gptModels    = @($models | Where-Object { $_ -notmatch '^claude' })
$claudeModels = @($models | Where-Object { $_ -match '^claude' })
if ($gptModels.Count -eq 0) { $gptModels = $models }
$hasGpt       = ($gptModels.Count -gt 0)
$hasClaude    = ($claudeModels.Count -gt 0)

$codexModel = $null
if ($hasGpt) {
    if ($Model -and ($gptModels -contains $Model)) {
        $codexModel = $Model
    } else {
        $pref = @('gpt-6.1-sol','gpt-6-sol','gpt-6-astra','gpt-6-luna','gpt-6.1-terra','gpt-5.6-sol','gpt-5.5') | Where-Object { $gptModels -contains $_ } | Select-Object -First 1
        $codexModel = if ($pref) { $pref } else { $gptModels[0] }
    }
}

$claudeModel = $null
if ($hasClaude) {
    if ($Model -and ($claudeModels -contains $Model)) {
        $claudeModel = $Model
    } else {
        $prefC = @('claude-opus-5-5','claude-sonnet-5-5','claude-opus-5','claude-sonnet-5') | Where-Object { $claudeModels -contains $_ } | Select-Object -First 1
        $claudeModel = if ($prefC) { $prefC } else { $claudeModels[0] }
    }
}

$stamp = Get-Date -Format 'yyyyMMdd-HHmmss'
$backup = Join-Path $backupRoot $stamp
$null = New-Item -ItemType Directory -Path $backup -Force
$map = @{}
Backup-File (Join-Path $codexHome 'config.toml') 'config.toml' $backup $map
Backup-File $claudePath 'claude-settings.json' $backup $map
Backup-File $opencodePath 'opencode.json' $backup $map

foreach ($scope in @('Process', 'User')) {
    try {
        [Environment]::SetEnvironmentVariable('OPENAI_BASE_URL', $null, $scope)
        [Environment]::SetEnvironmentVariable('OPENAI_API_KEY',  $null, $scope)
        [Environment]::SetEnvironmentVariable('CODEX_API_KEY',   $null, $scope)
        [Environment]::SetEnvironmentVariable('CODEX_ELECTRON_ENABLE_WINDOWS_COMPUTER_USE', '1', $scope)
        [Environment]::SetEnvironmentVariable('GATEWAY_API_KEY', $key, $scope)
    } catch { }
}
Broadcast-EnvironmentChange

# Locate installed codex.exe (including Microsoft Store Appx package) BEFORE stopping processes
$codexExe = $null
$cmdCodex = Get-Command codex.exe -ErrorAction SilentlyContinue | Select-Object -First 1
if ($cmdCodex) { $codexExe = $cmdCodex.Source }
if (-not $codexExe) {
    $bDir = Join-Path $env:LOCALAPPDATA 'OpenAI\Codex\bin'
    if (Test-Path -LiteralPath $bDir) {
        $found = Get-ChildItem -LiteralPath $bDir -Filter 'codex.exe' -Recurse -ErrorAction SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1
        if ($found) { $codexExe = $found.FullName }
    }
}
if (-not $codexExe -and (Get-Command Get-AppxPackage -ErrorAction SilentlyContinue)) {
    try {
        foreach ($pkg in @(Get-AppxPackage | Where-Object { $_.Name -match '^OpenAI\.(Codex|ChatGPT)' })) {
            if (-not $pkg.InstallLocation) { continue }
            foreach ($rel in @('app\resources\codex.exe', 'resources\codex.exe', 'app\resources\bin\codex.exe', 'codex.exe')) {
                $p = Join-Path $pkg.InstallLocation $rel
                if (Test-Path -LiteralPath $p) { $codexExe = $p; break }
            }
            if ($codexExe) { break }
        }
    } catch { }
}

$nativeCat = $null
if ($codexExe -and (Test-Path -LiteralPath $codexExe)) {
    $stage = Join-Path ([IO.Path]::GetTempPath()) ('Gateway-Cat-' + [Guid]::NewGuid().ToString('N'))
    $null = New-Item -ItemType Directory -Path $stage -Force
    try {
        $psiCat = New-Object Diagnostics.ProcessStartInfo
        $psiCat.FileName = $codexExe
        $psiCat.Arguments = 'debug models --bundled'
        $psiCat.UseShellExecute = $false
        $psiCat.CreateNoWindow = $true
        $psiCat.RedirectStandardOutput = $true
        $psiCat.RedirectStandardError = $true
        $psiCat.StandardOutputEncoding = [Text.Encoding]::UTF8
        $psiCat.WorkingDirectory = $stage
        $psiCat.EnvironmentVariables['CODEX_HOME'] = $stage
        $pCat = [Diagnostics.Process]::Start($psiCat)
        $rawCat = $pCat.StandardOutput.ReadToEnd()
        [void]$pCat.WaitForExit(12000)
        if ($rawCat) { $nativeCat = $rawCat | ConvertFrom-Json }
    } catch { } finally {
        Remove-Item -LiteralPath $stage -Recurse -Force -ErrorAction SilentlyContinue
    }
}

# Stop running processes silently and clean previous files before applying
Get-Process -ErrorAction SilentlyContinue | Where-Object {
    $_.ProcessName -match '^(codex|codex-desktop|chatgpt|node_repl|codex-computer-use-swift|codex-command-runner|codex-windows-sandbox-setup)$'
} | Stop-Process -Force -ErrorAction SilentlyContinue
Start-Sleep -Milliseconds 350

$installed = @()

# 1. CODEX (Installed strictly with the real models from $gptModels)
if (($targetList -contains 'codex') -and $hasGpt -and $codexModel) {
    Write-Output '[LOG] Preparando ambiente e aplicando perfil no Codex...'
    $null = New-Item -ItemType Directory -Path $codexHome -Force

    foreach ($oldFile in @(
        'config.toml',
        'requirements.toml',
        'models-catalog.json',
        'gateway-models-http.json',
        'gateway-model-catalog.json',
        'AGENTS.md'
    )) {
        $oldPath = Join-Path $codexHome $oldFile
        if (Test-Path -LiteralPath $oldPath) {
            Remove-Item -LiteralPath $oldPath -Force -ErrorAction SilentlyContinue
        }
    }
    foreach ($oldToml in @(Get-ChildItem -LiteralPath $codexHome -Filter '*.toml' -File -ErrorAction SilentlyContinue)) {
        Remove-Item -LiteralPath $oldToml.FullName -Force -ErrorAction SilentlyContinue
    }
    foreach ($oldJson in @(Get-ChildItem -LiteralPath $codexHome -Filter '*-models-*.json' -File -ErrorAction SilentlyContinue)) {
        Remove-Item -LiteralPath $oldJson.FullName -Force -ErrorAction SilentlyContinue
    }
    $oldPolicyDir = Join-Path ([Environment]::GetFolderPath('CommonApplicationData')) 'OpenAI\Codex'
    if (Test-Path -LiteralPath $oldPolicyDir) {
        foreach ($oldPolFile in @(Get-ChildItem -LiteralPath $oldPolicyDir -File -ErrorAction SilentlyContinue)) {
            Remove-Item -LiteralPath $oldPolFile.FullName -Force -ErrorAction SilentlyContinue
        }
    }
    $oldMcpDir = Join-Path $codexHome 'mcp'
    if (Test-Path -LiteralPath $oldMcpDir) {
        Remove-Item -LiteralPath $oldMcpDir -Recurse -Force -ErrorAction SilentlyContinue
    }

    $mcpDir = Join-Path $codexHome 'mcp'
    $null = New-Item -ItemType Directory -Path $mcpDir -Force
    $mcpPowerpackPath = Join-Path $mcpDir 'codex-powerpack-mcp.cjs'
    $mcpNodeReplPath  = Join-Path $mcpDir 'codex-node-repl-mcp.cjs'
    $mcpCompUsePath   = Join-Path $mcpDir 'codex-computer-use-mcp.cjs'
    $mcpSeqThinkPath  = Join-Path $mcpDir 'codex-sequential-thinking-mcp.cjs'
    $mcpMemoryPath    = Join-Path $mcpDir 'codex-memory-mcp.cjs'
    $mcpContext7Path  = Join-Path $mcpDir 'codex-context7-mcp.cjs'

    [IO.File]::WriteAllBytes($mcpPowerpackPath, [Convert]::FromBase64String(''))
    [IO.File]::WriteAllBytes($mcpNodeReplPath,  [Convert]::FromBase64String(''))
    [IO.File]::WriteAllBytes($mcpCompUsePath,   [Convert]::FromBase64String(''))
    [IO.File]::WriteAllBytes($mcpSeqThinkPath,  [Convert]::FromBase64String(''))
    [IO.File]::WriteAllBytes($mcpMemoryPath,    [Convert]::FromBase64String(''))
    [IO.File]::WriteAllBytes($mcpContext7Path,  [Convert]::FromBase64String(''))
    [IO.File]::WriteAllBytes((Join-Path $codexHome 'AGENTS.md'), [Convert]::FromBase64String(''))

    # STRICT REAL MODELS ONLY: put chosen model first, followed ONLY by the real models from $gptModels
    $realCatalogIds = New-Object 'Collections.Generic.List[string]'
    [void]$realCatalogIds.Add([string]$codexModel)
    foreach ($id in $gptModels) {
        if ($id -and -not $realCatalogIds.Contains([string]$id)) {
            [void]$realCatalogIds.Add([string]$id)
        }
    }

    $finalModels = New-Object 'Collections.Generic.List[object]'
    $templateEntry = $null
    if ($nativeCat -and $nativeCat.models) {
        $templateEntry = @($nativeCat.models | Where-Object { $_.slug -ceq 'gpt-6.1-sol' -or $_.slug -match '^gpt-5' } | Select-Object -First 1)[0]
        if (-not $templateEntry) { $templateEntry = $nativeCat.models[0] }
    }

    $prio = 0
    foreach ($mId in $realCatalogIds) {
        $existing = $null
        if ($nativeCat -and $nativeCat.models) {
            $existing = @($nativeCat.models | Where-Object { $_.slug -ceq $mId } | Select-Object -First 1)[0]
        }
        if ($existing) {
            $clone = ($existing | ConvertTo-Json -Depth 100 -Compress) | ConvertFrom-Json
            $clone.visibility = 'list'
            $clone.supported_in_api = $true
            $clone.priority = $prio
            $finalModels.Add($clone)
        } elseif ($templateEntry) {
            $clone = ($templateEntry | ConvertTo-Json -Depth 100 -Compress) | ConvertFrom-Json
            $clone.slug = $mId
            $clone.display_name = $mId
            $clone.visibility = 'list'
            $clone.supported_in_api = $true
            $clone.priority = $prio
            $finalModels.Add($clone)
        } else {
            $finalModels.Add([ordered]@{
                slug = $mId
                display_name = $mId
                description = 'Gateway Native Model'
                default_reasoning_level = 'high'
                supported_reasoning_levels = @(
                    @{ effort = 'low'; description = 'Low' },
                    @{ effort = 'medium'; description = 'Medium' },
                    @{ effort = 'high'; description = 'High' },
                    @{ effort = 'xhigh'; description = 'Extra High' }
                )
                shell_type = 'unified_exec'
                visibility = 'list'
                supported_in_api = $true
                priority = $prio
                model_messages = [ordered]@{
                    instructions_template = 'You are Codex, an agentic coding assistant. Use available tools (including spawn_agent, wait_agent, send_input, close_agent, update_plan, exec_command, and apply_patch) when useful and complete tasks end to end.'
                    instructions_variables = $null
                    approvals = $null
                    collaboration_modes = $null
                    auto_review = $null
                    permissions = $null
                    multi_agent = $null
                    token_budget = $null
                    confirmation_policies = $null
                    guardian_v2 = $null
                }
                apply_patch_tool_type = 'function'
                web_search_tool_type = 'text_and_image'
                supports_search_tool = $true
                context_window = 400000
                max_output_tokens = 128000
                auto_compact_token_limit = 350000
                effective_context_window_percent = 95
                input_modalities = @('text', 'image')
                supports_parallel_tool_calls = $true
                prefer_websockets = $false
                include_plugin_usage_instructions = $true
                include_apps_usage_instructions = $true
                include_skills_usage_instructions = $true
                node_repl_disabled = $false
                tool_mode = 'standard'
                multi_agent_version = 'v2'
                multi_agent_reasoning_effort = 'high'
            })
        }
        $prio++
    }

    $catalogPath = Join-Path $codexHome 'gateway-models-http.json'
    Write-Utf8 $catalogPath ((@{ models = $finalModels.ToArray() }) | ConvertTo-Json -Depth 100)

    if ($GlobalPolicy -eq '1') {
        try {
            $policyDir = Join-Path ([Environment]::GetFolderPath('CommonApplicationData')) 'OpenAI\Codex'
            $policyPath = Join-Path $policyDir 'requirements.toml'
            $policyText = @(
                '# Gateway 7.0 - Windows inference routing. No account credentials.',
                'model_provider = "gateway"',
                '',
                '[model_providers.gateway]',
                'name = "Gateway"',
                ('base_url = "' + $cleanEp + '"'),
                'wire_api = "responses"',
                'env_key = "GATEWAY_API_KEY"',
                'requires_openai_auth = true',
                'supports_websockets = false',
                'supports_standalone_web_search = true',
                '',
                '[model_providers.gateway.http_headers]',
                ('Authorization = "Bearer ' + $key + '"'),
                ('x-api-key = "' + $key + '"'),
                'X-Gateway-Tools-Compatibility = "functions-v1"',
                ''
            ) -join "`r`n"
            Write-Utf8 $policyPath $policyText
        } catch { }
    }

    $escapedCatPath = $catalogPath.Replace('\', '/')
    $nodeCmd = 'node'
    $cmdNode = Get-Command node.exe -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($cmdNode) { $nodeCmd = $cmdNode.Source.Replace('\', '/') }

    $configPath = Join-Path $codexHome 'config.toml'
    $cfgLines = @(
        '# >>> GATEWAY MANAGED >>>',
        ('model = "' + $codexModel + '"'),
        'model_provider = "gateway"',
        ('model_catalog_json = "' + $escapedCatPath + '"'),
        'model_reasoning_effort = "xhigh"',
        'model_reasoning_summary = "detailed"',
        'model_verbosity = "high"',
        'approval_policy = "on-request"',
        'approvals_reviewer = "auto_review"',
        'sandbox_mode = "workspace-write"',
        'web_search = "live"',
        '',
        '[windows]',
        'sandbox = "unelevated"',
        '',
        '[computer_use.windows]',
        'always_allowed_app_ids = ["explorer.exe", "chrome.exe", "msedge.exe", "Code.exe", "Unity.exe", "blender.exe", "powershell.exe", "cmd.exe", "notepad.exe"]',
        '',
        '[features]',
        'multi_agent = true',
        'plugins = true',
        'apps = true',
        'standalone_web_search = true',
        'network_proxy = false',
        '',
        '[sandbox_workspace_write]',
        'network_access = true',
        '',
        '[model_providers.gateway]',
        'name = "Gateway"',
        ('base_url = "' + $cleanEp + '"'),
        'env_key = "GATEWAY_API_KEY"',
        'wire_api = "responses"',
        'requires_openai_auth = true',
        'supports_websockets = false',
        'supports_standalone_web_search = true',
        '',
        '[model_providers.gateway.http_headers]',
        ('Authorization = "Bearer ' + $key + '"'),
        ('x-api-key = "' + $key + '"'),
        'X-Gateway-Tools-Compatibility = "functions-v1"',
        '',
        '[mcp_servers.computer_use]',
        ('command = "' + $nodeCmd + '"'),
        ('args = ["' + $mcpCompUsePath.Replace('\', '/') + '"]'),
        'enabled = true',
        'startup_timeout_sec = 30',
        'tool_timeout_sec = 120',
        '',
        '[mcp_servers.node_repl]',
        ('command = "' + $nodeCmd + '"'),
        ('args = ["' + $mcpNodeReplPath.Replace('\', '/') + '"]'),
        'enabled = true',
        'startup_timeout_sec = 30',
        'tool_timeout_sec = 120',
        '',
        '[mcp_servers.codex_powerpack]',
        ('command = "' + $nodeCmd + '"'),
        ('args = ["' + $mcpPowerpackPath.Replace('\', '/') + '"]'),
        'enabled = true',
        'startup_timeout_sec = 30',
        'tool_timeout_sec = 180',
        '',
        '[mcp_servers.sequential_thinking]',
        ('command = "' + $nodeCmd + '"'),
        ('args = ["' + $mcpSeqThinkPath.Replace('\', '/') + '"]'),
        'enabled = true',
        'startup_timeout_sec = 30',
        'tool_timeout_sec = 120',
        '',
        '[mcp_servers.memory]',
        ('command = "' + $nodeCmd + '"'),
        ('args = ["' + $mcpMemoryPath.Replace('\', '/') + '"]'),
        'enabled = true',
        'startup_timeout_sec = 30',
        'tool_timeout_sec = 120',
        '',
        '[mcp_servers.context7]',
        ('command = "' + $nodeCmd + '"'),
        ('args = ["' + $mcpContext7Path.Replace('\', '/') + '"]'),
        'enabled = true',
        'startup_timeout_sec = 30',
        'tool_timeout_sec = 120',
        '# <<< GATEWAY MANAGED <<<'
    )
    Write-Utf8 $configPath ($cfgLines -join "`r`n")
    Restrict-File $configPath

    foreach ($sub in @('sessions', 'archived_sessions')) {
        $sDir = Join-Path $codexHome $sub
        if (Test-Path -LiteralPath $sDir) {
            foreach ($jf in @(Get-ChildItem -LiteralPath $sDir -Filter '*.jsonl' -Recurse -File -ErrorAction SilentlyContinue)) {
                try {
                    $rawJ = [IO.File]::ReadAllText($jf.FullName, [Text.Encoding]::UTF8)
                    if ($rawJ -match '"model_provider(_id)?"\s*:\s*"(openai|openai_custom|codex_gateway|gateway_custom)"') {
                        $rawJ = [regex]::Replace($rawJ, '"model_provider"\s*:\s*"(openai|openai_custom|codex_gateway|gateway_custom)"', '"model_provider":"gateway"')
                        $rawJ = [regex]::Replace($rawJ, '"model_provider_id"\s*:\s*"(openai|openai_custom|codex_gateway|gateway_custom)"', '"model_provider_id":"gateway"')
                        Write-Utf8 $jf.FullName $rawJ
                    }
                } catch { }
            }
        }
    }

    $installed += ('Codex (' + $codexModel + ')')
}

# 2. CLAUDE CODE + CLAUDE DESKTOP (Only if real claude-* models exist in /models)
if (($targetList -contains 'claude-code' -or $targetList -contains 'claude-desktop') -and $hasClaude -and $claudeModel) {
    Write-Output '[LOG] Aplicando perfil no Claude...'
    $dir = Split-Path -Parent $claudePath
    if (-not (Test-Path -LiteralPath $dir)) { $null = New-Item -ItemType Directory -Path $dir -Force }
    $settings = @{}
    if (Test-Path -LiteralPath $claudePath) {
        try { $settings = Get-Content -LiteralPath $claudePath -Raw -Encoding UTF8 | ConvertFrom-Json | ConvertTo-Hashtable } catch { $settings = @{} }
    }
    if (-not $settings) { $settings = @{} }
    $settings['model'] = $claudeModel
    $settings['availableModels'] = $claudeModels
    $envMap = @{}
    if ($settings['env'] -is [hashtable]) { $envMap = $settings['env'] }
    $root = if ($cleanEp.ToLower().EndsWith('/v1')) { $cleanEp.Substring(0, $cleanEp.Length - 3).TrimEnd('/') } else { $cleanEp }
    foreach ($k in @('ANTHROPIC_BASE_URL','ANTHROPIC_AUTH_TOKEN','ANTHROPIC_API_KEY','ANTHROPIC_MODEL','ANTHROPIC_DEFAULT_OPUS_MODEL','ANTHROPIC_DEFAULT_SONNET_MODEL','ANTHROPIC_DEFAULT_HAIKU_MODEL','ANTHROPIC_SMALL_FAST_MODEL','CLAUDE_CODE_SUBAGENT_MODEL')) {
        $envMap[$k] = if ($k -eq 'ANTHROPIC_BASE_URL') { $root } elseif ($k -eq 'ANTHROPIC_AUTH_TOKEN' -or $k -eq 'ANTHROPIC_API_KEY') { $key } else { $claudeModel }
    }
    $settings['env'] = $envMap
    Write-Utf8 $claudePath ($settings | ConvertTo-Json -Depth 20)
    Restrict-File $claudePath
    $installed += ('Claude (' + $claudeModel + ')')
}

# 3. OPENCODE (Installed strictly with the real models from $gptModels)
if (($targetList -contains 'opencode') -and $hasGpt -and $codexModel) {
    Write-Output '[LOG] Aplicando perfil no opencode...'
    $data = @{}
    if (Test-Path -LiteralPath $opencodePath) {
        try { $data = Get-Content -LiteralPath $opencodePath -Raw -Encoding UTF8 | ConvertFrom-Json | ConvertTo-Hashtable } catch { $data = @{} }
    }
    if ($null -eq $data) { $data = @{} }
    if (-not ($data['provider'] -is [hashtable])) { $data['provider'] = @{} }
    $ocModelsMap = @{}
    foreach ($gm in $gptModels) {
        $ocModelsMap[$gm] = @{ name = $gm; limit = @{ context = 400000; output = 128000 }; reasoning = $true }
    }
    $data['provider']['gateway'] = @{
        npm = '@ai-sdk/openai-compatible'
        name = 'Gateway'
        options = @{ baseURL = $cleanEp; apiKey = $key }
        models = $ocModelsMap
    }
    $data['model'] = 'gateway/' + $codexModel
    Write-Utf8 $opencodePath ($data | ConvertTo-Json -Depth 30)
    Restrict-File $opencodePath
    $installed += ('opencode (' + $codexModel + ')')
}

# 4. HERMES AGENT
if (($targetList -contains 'hermes') -and $hasGpt -and $codexModel) {
    Write-Output '[LOG] Aplicando perfil no Hermes Agent...'
    $hermesYaml = @(
        "model:",
        "  default: $codexModel",
        "  provider: gateway",
        "  base_url: $cleanEp",
        "  api_mode: chat_completions",
        "  key_env: GATEWAY_API_KEY"
    ) -join "`r`n"
    Write-Utf8 $hermesPath $hermesYaml
    $installed += ('Hermes (' + $codexModel + ')')
}

# 5. OPENCLAW
if (($targetList -contains 'openclaw') -and $hasGpt -and $codexModel) {
    Write-Output '[LOG] Aplicando perfil no OpenClaw...'
    $ocData = @{
        mode = 'merge'
        providers = @{
            gateway = @{
                baseUrl = $cleanEp
                apiKey  = $key
                api     = 'openai-completions'
            }
        }
        agents = @{
            defaults = @{
                model = @{ primary = ('gateway/' + $codexModel) }
            }
        }
    }
    Write-Utf8 $openclawPath ($ocData | ConvertTo-Json -Depth 20)
    $installed += ('OpenClaw (' + $codexModel + ')')
}

$manifest = @{ version = $Version; endpoint = $cleanEp; model = $codexModel; targets = $installed; files = $map } | ConvertTo-Json -Depth 20
Write-Utf8 (Join-Path $backup 'manifest.json') $manifest
Restrict-File (Join-Path $backup 'manifest.json')

Broadcast-EnvironmentChange
Write-Output '[LOG] Configuracao aplicada. Os caminhos e metodos internos nao sao exibidos.'
Write-Output 'GATEWAY_INSTALL_OK'
